/*Table structure for table `elderly` */

DROP TABLE IF EXISTS `elderly`;

CREATE TABLE `elderly` (
  `elderly_id` bigint NOT NULL AUTO_INCREMENT COMMENT '老人ID，主键',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `id_card` varchar(18) COLLATE utf8mb4_general_ci NOT NULL COMMENT '身份证号（唯一）',
  `sex` char(1) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '性别：0/1',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '家庭住址',
  `emergency_contact` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '紧急联系人姓名',
  `emergency_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '紧急联系电话',
  `health_status` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '健康状况摘要',
  `admission_date` datetime DEFAULT NULL COMMENT '入住时间',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '居住状态：0-未入住，1-在住，2-已离院',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常，1-删除',
  PRIMARY KEY (`elderly_id`),
  UNIQUE KEY `uk_id_card` (`id_card`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='老人档案表';

