/*Table structure for table `health_record` */

DROP TABLE IF EXISTS `health_record`;

CREATE TABLE `health_record` (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '健康记录ID',
  `elderly_id` bigint NOT NULL COMMENT '老人ID',
  `recorder_id` bigint NOT NULL COMMENT '记录人用户ID',
  `record_time` datetime NOT NULL COMMENT '记录时间',
  `blood_pressure` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '血压（格式：120/80）',
  `heart_rate` int DEFAULT NULL COMMENT '心率（次/分钟）',
  `temperature` decimal(4,1) DEFAULT NULL COMMENT '体温（℃）',
  `weight` decimal(5,2) DEFAULT NULL COMMENT '体重（kg）',
  `blood_sugar` decimal(5,2) DEFAULT NULL COMMENT '血糖（mmol/L）',
  `symptom_desc` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '症状描述',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '其他备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常，1-删除',
  PRIMARY KEY (`record_id`),
  KEY `idx_elderly_time` (`elderly_id`,`record_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='健康档案记录表';

/*Data for the table `health_record` */

insert  into `health_record`(`record_id`,`elderly_id`,`recorder_id`,`record_time`,`blood_pressure`,`heart_rate`,`temperature`,`weight`,`blood_sugar`,`symptom_desc`,`remark`,`create_by`,`create_time`,`update_by`,`update_time`,`del_flag`) values (1,1,102,'2025-12-15 00:00:00','130/85',78,'36.5','62.30','6.20','精神良好，无不适','入院记录',NULL,'2025-12-18 11:50:05',NULL,'2026-03-10 22:07:09',0),(2,2,1,'2026-03-10 00:00:00','125/80',77,'36.6','70.00','5.80','精神良好，无不适','入院记录',NULL,'2025-12-10 22:07:27',NULL,'2026-03-11 09:23:39',0);

/*Table structure for table `medical_order` */

DROP TABLE IF EXISTS `medical_order`;

CREATE TABLE `medical_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '医嘱ID',
  `elderly_id` bigint NOT NULL COMMENT '老人ID ',
  `order_content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医嘱内容',
  `medication_advice` text COLLATE utf8mb4_unicode_ci COMMENT '用药建议',
  `doctor_id` bigint NOT NULL COMMENT '医生ID ',
  `order_date` datetime NOT NULL COMMENT '医嘱日期',
  `medication_id` bigint DEFAULT NULL COMMENT '用药表ID ',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
